        { "reverse.cpp", "#include <iostream>\n\nstruct Node {\n    int value;\n    Node* next;\n};\n\nNode* reverse(Node* node) {\n    Node* previous = nullptr;\n    while (node != nullptr) {\n        Node* following = node->next;\n        node->next = previous;\n        node = following;\n    }\n    return previous;\n}\n\nint main() {\n    Node third{3, nullptr}, second{2, &third}, first{1, &second};\n    bool written = false;\n    for (Node* node = reverse(&first); node != nullptr; node = node->next) {\n        std::cout << (written ? \" \" : \"\") << node->value;\n        written = true;\n    }\n    std::cout << std::endl;\n    return 0;\n}\n", "logic-cpp-previous-never-moved", 12, 13, 0, "        previous = node;" },
